create table if not exists public.print_orders (id bigint generated by default as identity primary key, customer_name text not null, phone text not null, print_type text not null, quantity integer not null default 1 check(quantity>0), details text, file_path text, created_at timestamptz not null default now());
alter table public.print_orders enable row level security;
drop policy if exists "Allow public order submissions" on public.print_orders;
create policy "Allow public order submissions" on public.print_orders for insert to anon, authenticated with check(length(trim(customer_name))>0 and length(trim(phone))>0 and quantity>0);
-- Supabase Storage-এ private print-files bucket তৈরি করুন; প্রয়োজনমতো upload policy সেট করুন।